#!/bin/sh
# Builds `gamma`, the compiler in compiler/, from the seed in bootstrap/seed with nothing
# but a C compiler.
#
#   bootstrap/build.sh [OUT_DIR]       (default: target/bootstrap)
#
# The seed is the C that the compiler generated for its own sources (bootstrap/seed/SOURCE
# names them), as the translation units a build of the compiler compiles. Compiling it
# gives gamma0; gamma0 builds the compiler of the current sources (gamma1), and gamma1
# builds itself again (gamma), so that the result is generated by the current compiler and
# not by the seed's. gamma0 takes the seed's objects for the units that are still the same
# in the current sources, so only what changed since the seed is compiled twice. `CC`,
# `CFLAGS` and `JOBS` (default: the number of processors) are honored.
set -eu

here=$(cd "$(dirname "$0")" && pwd)
root=$(dirname "$here")
out=${1:-$root/target/bootstrap}
cc=${CC:-cc}
jobs=${JOBS:-$(getconf _NPROCESSORS_ONLN 2>/dev/null || echo 4)}
mkdir -p "$out"
out=$(cd "$out" && pwd)

# The flags the compiler compiles the units of itself with (BASE_CFLAGS, the optimization
# of a Checked build and the check of split units in compiler/driver/native.gm), so that
# the objects are the ones its build would make.
flags="-std=gnu11 -w -Wno-free-nonheap-object -fwrapv -fno-strict-aliasing -ffp-contract=off -pthread -O2 -Werror=implicit-function-declaration"

echo "bootstrap: compiling the seed with $cc"
# Every unit, the largest first, $jobs at a time; a failure stops the build. Objects of
# another seed must not be linked.
rm -rf "$out/seed"
mkdir -p "$out/seed"
GM_CC=$cc
GM_FLAGS="$flags ${CFLAGS:-}"
GM_SEED=$here/seed
GM_OBJECTS=$out/seed
export GM_CC GM_FLAGS GM_SEED GM_OBJECTS
# shellcheck disable=SC2016
if ! (cd "$here/seed" && ls -S ./*.c) | sed -e 's|^\./||' -e 's|\.c$||' |
    xargs -P "$jobs" -n 1 sh -c '$GM_CC $GM_FLAGS -c "$GM_SEED/$1.c" -o "$GM_OBJECTS/$1.o"' sh; then
    echo "bootstrap: compiling the seed failed" >&2
    exit 1
fi
$cc -pthread -o "$out/gamma0" "$out"/seed/*.o -lm

# Builds use the repository's standard library and runtime (by the relative names the seed
# was generated with: they are part of the C), and a cache of their own.
cd "$root"
GAMMA_STD=lib/std
GAMMA_RUNTIME=runtime
GAMMA_CACHE_DIR="$out/cache"
export GAMMA_STD GAMMA_RUNTIME GAMMA_CACHE_DIR
echo "bootstrap: building gamma with the seed's compiler"
# Each seed object is named after the hash of its unit's text, which is how gamma0 finds it.
GAMMA_UNIT_OBJECTS="$out/seed" "$out/gamma0" build compiler -o "$out/gamma1"
echo "bootstrap: building gamma with itself"
"$out/gamma1" build compiler -o "$out/gamma"
echo "bootstrap: $out/gamma"
